def gen(rng):
    def fmt(nuts, bolts):
        return str(len(nuts)) + '\n' + ' '.join(map(str, nuts)) + '\n' + ' '.join(map(str, bolts))
    def rnd(n, hi):
        nuts = rng.sample(range(1, hi + 1), n)
        bolts = nuts[:]
        rng.shuffle(bolts)
        return fmt(nuts, bolts)
    tests = [
        fmt([1], [1]),
        fmt([10**9], [10**9]),
        fmt([1, 2], [2, 1]),
        fmt([1, 2], [1, 2]),
        fmt([5, 9, 1], [5, 9, 1]),
        fmt([1, 2, 3, 4, 5], [5, 4, 3, 2, 1]),
    ]
    for n in (3, 4, 6, 8, 10, 12):
        for _ in range(3):
            tests.append(rnd(n, 40))
    tests.append(rnd(2000, 10**9))
    # sorted inputs, adversarial for a fixed first-element pivot (kept below the recursion limit)
    tests.append(fmt(list(range(1, 4001)), list(range(1, 4001))))
    tests.append(fmt(list(range(1, 4001)), list(range(4000, 0, -1))))
    tests.append(rnd(100000, 10**9))
    tests.append(rnd(100000, 100000))
    return tests

